 ('S03 case_name empty name', A, 'NF >= 4 && $4 != "" && $2 != "sweep"', 'NF >= 4 && $2 != "sweep"', TR),
 ('S05 point_reached effect only', A, "'$2 == e && $3 == s { f = 1 }", "'$2 == e { f = 1 }", TR),
 ('S15 retry never', A, '        acmd retry publish --limit-s 600\n', '', TR),
 ('S16 dhook no freeze', A, '        freeze\n        sleep 3\n        abg publish publish --limit-s 600 "$@"', '        abg publish publish --limit-s 600 "$@"', TR),
 ('S17 holds not read before release', A, '    zfs list -H -t snapshot -o name -r "$POOL" | xargs -r zfs holds -H > "$CDIR/holds.txt" 2> "$CDIR/holds.err" \\\n        || rig_error "zfs holds failed: $(tail -n 2 "$CDIR/holds.err")"\n', '    : > "$CDIR/holds.txt"\n', TR),
 ('S22 settle without age', A, '    acmd settle settle --limit-s 600 "${CASE_AGE[@]}"', '    acmd settle settle --limit-s 600', TR),
