 ('T09 published: gone line overwrites', A, '"$n" >> "$RDIR/published-gone.tsv"', '"$n" > "$RDIR/published-gone.tsv"', TR),
 ('S21a vrun: the run dir itself', A, 'vrun() { printf \'%s/v-%x-%x\' "$RUN" "$(stat -c %d "$VOL")" "$(stat -c %i "$VOL")"; }', 'vrun() { printf \'%s\' "$RUN"; }', TR),
 ('U11 reserve: hung stop not killed', A, '        kill -9 "$SERVE_PID" 2>/dev/null || true\n        serve_end 10 || rig_error "skyzfsd serve $SERVE_K did not end 10 s after SIGKILL"', '        serve_end 10 || rig_error "skyzfsd serve $SERVE_K did not end 10 s after SIGKILL"', TR),
 ('U12 reserve: hung stop not a verdict', A, '        verdict daemon_stopped "skyzfsd serve $SERVE_K did not end 60 s after SIGTERM"\n', '', TR),
 ('U13 acase: recover not called', A, '    "scen_$SCEN" "${4:-}" "${hooks[@]}"\n    recover\n', '    "scen_$SCEN" "${4:-}" "${hooks[@]}"\n', TR),
 ('U14 destroy: goes on after its error', A, '            mv "$CDIR/destroy.log" "$CDIR/destroy-failed.log"\n            return 0\n        fi\n        mark "destroyed-$id"', '            mv "$CDIR/destroy.log" "$CDIR/destroy-failed.log"\n        fi\n        mark "destroyed-$id"', TR),
 ('U15 destroy: log kept on error', A, '            mv "$CDIR/destroy.log" "$CDIR/destroy-failed.log"\n            return 0', '            return 0', TR),
 ('U16 gone: log kept on error', A, '        mv "$CDIR/destroy.log" "$CDIR/destroy-failed.log"\n    fi\n}\nscen_unmarked', '    fi\n}\nscen_unmarked', TR),
 ('U18 dhook: no asked verdict', A, '        wait_point asked after 60 || verdict asked "the agent did not reach asked:after in 60 s"', '        wait_point asked after 60 || true', TR),
 ('U19 late: no asked verdict, goes on', A, '    wait_point asked after 60 || { verdict asked "the agent did not reach asked:after in 60 s"; return 0; }', '    wait_point asked after 60 || true', TR),
 ('U20 late: no landed verdict', A, '    snaprow "$t" landed.txt || { verdict landed "snap/$t had not landed 120 s after the thaw"; return 0; }', '    snaprow "$t" landed.txt || true', TR),
 ('U21 dhook: lost pid not an error', A, '        serve_end 5 || { case_error "the daemon\'s pid went away and serve_end did not see it end"; return 0; }', '        serve_end 5 || true', TR),
 ('U30 serve_log: always serve-K', A, 'serve_log() { if [ "$1" = 1 ]; then echo "$RDIR/serve.log"; else echo "$RDIR/serve-$1.log"; fi; }', 'serve_log() { echo "$RDIR/serve-$1.log"; }', TR),
 ('V01 rig_error: hook 0 passes', C, '        [ "$rc" = 1 ] || rc=2\n', '', TRC),
 ('V02 rig_error: hook not cleared', C, '        ON_RIG_ERROR=""\n        "$h" "$m" || rc=$?', '        "$h" "$m" || rc=$?', TRC),
 ('V05 rig_error: hook any non-zero kept', C, '        [ "$rc" = 1 ] || rc=2\n', '        [ "$rc" != 0 ] || rc=2\n', TRC),
