 ('S18r destroy keeps hold', A, '{ lim 60 zfs release "$HOLD_TAG" "$POOL@$t" && lim 60 zfs destroy "$POOL@$t"; }', '{ lim 60 zfs destroy "$POOL@$t"; }', TR),
 ('U05r recover: no SIGCONT', A, '        kill -CONT "$AGENT_PID" 2>/dev/null || true\n        kill -9 "$AGENT_PID" 2>/dev/null || true\n        wait "$AGENT_PID"', '        kill -9 "$AGENT_PID" 2>/dev/null || true\n        wait "$AGENT_PID"', TR),
 ('U05q quiet: no SIGCONT', A, '        kill -CONT "$AGENT_PID" 2>/dev/null || true\n        kill -9 "$AGENT_PID" 2>/dev/null || true\n        for _i', '        kill -9 "$AGENT_PID" 2>/dev/null || true\n        for _i', TR),
 # New: akill_serve and its callers (D10).
 ('X01 akill: never a verdict', A, '    [ "$rc" = 137 ] || verdict daemon_serving', '    true || verdict daemon_serving', TR),
 ('X02 akill: status not taken', A, '    wait "$SERVE_PID" 2>/dev/null || rc=$?\n    SERVE_PID=""\n    [ "$rc" = 137 ]', '    SERVE_PID=""\n    [ "$rc" = 137 ]', TR),
 ('X03 restart: kill_serve again', A, '    if wait_point asked after 60; then\n        akill_serve\n        thaw', '    if wait_point asked after 60; then\n        kill_serve\n        thaw', TR),
 ('X04 late: kill_serve again', A, '    akill_serve\n    serve_again\n    mark "continued-', '    kill_serve\n    serve_again\n    mark "continued-', TR),
 ('X04b late: the daemon not killed', A, '    akill_serve\n    serve_again\n    mark "continued-', '    serve_again\n    mark "continued-', TR),
 # D9.
 ('X05 recover: the exemption for every scenario', A, '        if [ "$SCEN" = dhook ] && [ -s "$CDIR/rig-error.txt" ]; then', '        if [ -s "$CDIR/rig-error.txt" ]; then', TR),
 ('X06 recover: the exemption but in plain', A, '        if [ "$SCEN" = dhook ] && [ -s "$CDIR/rig-error.txt" ]; then', '        if [ "$SCEN" != plain ] && [ -s "$CDIR/rig-error.txt" ]; then', TR),
 ('X06b recover: dhook always exempt', A, '        if [ "$SCEN" = dhook ] && [ -s "$CDIR/rig-error.txt" ]; then', '        if [ "$SCEN" = dhook ]; then', TR),
 ('X07 destroy: no asked never a verdict', A, '    else\n        [ -n "$KILL" ] || verdict asked "the agent did not reach asked:after in 60 s"\n    fi\n    thaw\n    await_agent publish 700\n}', '    fi\n    thaw\n    await_agent publish 700\n}', TR),
 ('X08 restart: no asked never a verdict', A, '        [ -n "$KILL" ] || verdict asked "the agent did not reach asked:after in 60 s"\n        thaw\n    fi', '        thaw\n    fi', TR),
 ('X09 destroy: wait 300 again', A, '        frozen_until_withdrawn\n    else', '        frozen_until_withdrawn\n        thaw; await_agent publish 300; return 0\n    else', TR),
 ('X10 tooold: wait 300 again', A, '    await_agent publish 400', '    await_agent publish 300', TR),
 ('X11 both: wait 300 again', A, '    abg publish publish --limit-s 600 "$@"\n    await_agent publish 700\n    # As kill_serve', '    abg publish publish --limit-s 600 "$@"\n    await_agent publish 300\n    # As kill_serve', TR),
 ('X12 asettle: no list of the snapshots after', A, '    zfs list -H -o name -t snapshot -r "$POOL" > "$CDIR/snapshots-after.txt" 2> "$CDIR/snapshots-after.err" \\\n        || rig_error "zfs list of $POOL\'s snapshots after the case failed: $(tail -n 2 "$CDIR/snapshots-after.err")"\n', '    : > "$CDIR/snapshots-after.txt"\n', TR),
 ('X12b asettle: the list before the retry', A, '    if [ -n "$t" ] && snaprow "$t" snaprow.txt; then\n        published "$t"', '    zfs list -H -o name -t snapshot -r "$POOL" > "$CDIR/snapshots-after.txt" 2> /dev/null || true\n    if [ -n "$t" ] && snaprow "$t" snaprow.txt; then\n        published "$t"', TR),
 ('X13 acase: CDIR kept', A, '    # No case under way: the rig\'s error after it names none.\n    CDIR=""\n', '', TR),
 ('X14 begin: no daemon hook', A, '    ON_DAEMON_WRONG=agent_daemon_wrong\n', '', TR),
 ('X15 daemon_wrong: no course dir', A, '    local c=${CDIR:-$RDIR/cases/course}', '    local c=${CDIR:-$RDIR}', TR),
 # D7: agent_judged and agent_quiet.
 ('X16 judged: no quiet', A, '    agent_quiet\n    # shellcheck disable=SC2086 # CHECK is a command line\n    $CHECK "$NAME" "$RDIR" "$RDIR/requests.tsv" -', '    # shellcheck disable=SC2086 # CHECK is a command line\n    $CHECK "$NAME" "$RDIR" "$RDIR/requests.tsv" -', TR),
 ('X17 judged: quiet only with no check', A, '    [ "$CHECK" != none ] || return 2\n    agent_quiet\n', '    [ "$CHECK" != none ] || { agent_quiet; return 2; }\n', TR),
 ('X18 quiet: the agent not killed', A, '        kill -9 "$AGENT_PID" 2>/dev/null || true\n        for _i', '        for _i', TR),
 ('X19 quiet: the store not thawed', A, '        bash -c "$S3_UP" >> "$RDIR/s3.log" 2>&1 && S3_IS_DOWN=""\n', '', TR),
 ('X20 quiet: the watcher left paused', A, '        bash -c "$S3_UP" >> "$RDIR/s3.log" 2>&1 && S3_IS_DOWN=""\n        rm -f "$WORK/watch.pause"\n', '        bash -c "$S3_UP" >> "$RDIR/s3.log" 2>&1 && S3_IS_DOWN=""\n', TR),
 ('X21 quiet: the writer not asked to stop', A, '        touch "$WORK/writer.stop"\n        for _i in $(seq 1 120); do kill -0 "$WRITER" 2>/dev/null || break; sleep 0.5; done\n        kill -9 "$WRITER" 2>/dev/null || true\n        kill -0', '        for _i in $(seq 1 120); do kill -0 "$WRITER" 2>/dev/null || break; sleep 0.5; done\n        kill -9 "$WRITER" 2>/dev/null || true\n        kill -0', TR),
 ('X22 quiet: the export fatal (z)', A, '    if lim 120 zpool export "$POOL" > "$RDIR/judged-export.log" 2>&1; then', '    if z 120 zpool export "$POOL" > "$RDIR/judged-export.log" 2>&1; then', TR),
 ('X23 quiet: no export', A, '    if lim 120 zpool export "$POOL" > "$RDIR/judged-export.log" 2>&1; then', '    if true; then', TR),
 ('X24 quiet: no session_end', A, '    session_end\n    if lim 120 zpool export', '    if lim 120 zpool export', TR),
 ('X25 quiet: the writer waited for unbounded', A, '        kill -0 "$WRITER" 2>/dev/null || wait "$WRITER" 2>/dev/null || true', '        wait "$WRITER" 2>/dev/null || true', TR),
 ('X26 quiet: the agent waited for unbounded', A, '        for _i in $(seq 1 20); do kill -0 "$AGENT_PID" 2>/dev/null || break; sleep 0.25; done\n        kill -0 "$AGENT_PID" 2>/dev/null || wait "$AGENT_PID" 2>/dev/null || true', '        wait "$AGENT_PID" 2>/dev/null || true', TR),
 ('X27 quiet: AGENT_PID kept', A, '        kill -0 "$AGENT_PID" 2>/dev/null || wait "$AGENT_PID" 2>/dev/null || true\n        AGENT_PID=""\n', '        kill -0 "$AGENT_PID" 2>/dev/null || wait "$AGENT_PID" 2>/dev/null || true\n', TR),
 # D10 in cut-record.sh.
 ('Y01 cleanup: no hook', C, '    if [ "$rc" != 0 ] && [ -n "$ON_RIG_ERROR" ]; then', '    if false; then', TRC),
 ('Y02 cleanup: hook not cleared before it runs', C, '        local h=$ON_RIG_ERROR hrc=0\n        ON_RIG_ERROR=""\n', '        local h=$ON_RIG_ERROR hrc=0\n', TRC),
 ('Y03 cleanup: the hook\'s status kept as is', C, '        if [ "$hrc" = 1 ]; then rc=1; else rc=2; fi', '        rc=$hrc', TRC),
 ('Y04 cleanup: no line', C, '        printf \'%s\\trig error\\ta command failed (status %s); the job log names it\\n\' "$NAME" "$rc" >> "$OUT/recordings.tsv"\n        "$h"', '        "$h"', TRC),
 ('Y05 daemon_wrong: no hook, goes on', C, '    [ -n "$ON_DAEMON_WRONG" ] || rig_error "$2"', '    [ -n "$ON_DAEMON_WRONG" ] || return 0', TRC),
 ('Y06 serve_start: no verdict', C, '            [ -z "$ON_DAEMON_WRONG" ] || "$ON_DAEMON_WRONG" daemon_ready "$m"\n', '', TRC),
 ('Y07 serve_start: no status', C, '            if serve_end 1; then st=$SERVE_RC; fi\n            SERVE_PID=""\n            m=', '            SERVE_PID=""\n            m=', TRC),
 ('Y07b serve_start: verdict, and goes on', C, '            [ -z "$ON_DAEMON_WRONG" ] || "$ON_DAEMON_WRONG" daemon_ready "$m"\n            rig_error "$m"', '            [ -z "$ON_DAEMON_WRONG" ] || { "$ON_DAEMON_WRONG" daemon_ready "$m"; break; }\n            rig_error "$m"', TRC),
 ('Y08 end_daemon: a stop not 0, the rig\'s error', C, '        daemon_wrong daemon_stopped "skyzfsd serve ended with $SERVE_RC on SIGTERM: $(tail -n 2 "$SERVE_LOG")"', '        rig_error "skyzfsd serve ended with $SERVE_RC on SIGTERM: $(tail -n 2 "$SERVE_LOG")"', TRC),
 ('Y09 end_daemon: a hung stop, the rig\'s error', C, '        daemon_wrong daemon_stopped "skyzfsd serve did not end 60 s after SIGTERM: $(tail -n 2 "$SERVE_LOG")"', '        rig_error "skyzfsd serve did not end 60 s after SIGTERM"', TRC),
 ('Y10 end_daemon: a hung stop not killed', C, '        kill -9 "$SERVE_PID" 2>/dev/null || true\n        serve_end 10 || rig_error "skyzfsd serve did not end 10 s after SIGKILL"', '        serve_end 10 || rig_error "skyzfsd serve did not end 10 s after SIGKILL"', TRC),
 ('Y11 end_daemon: the first log', C, '        daemon_wrong daemon_stopped "skyzfsd serve ended with $SERVE_RC on SIGTERM: $(tail -n 2 "$SERVE_LOG")"', '        daemon_wrong daemon_stopped "skyzfsd serve ended with $SERVE_RC on SIGTERM: $(tail -n 2 "$RDIR/serve.log")"', TRC),
 ('Y12 end: hooks cleared after the check', C, '    # Recorded: a course\'s hooks are done, and its check is the end\'s.\n    ON_RIG_ERROR=""; ON_DAEMON_WRONG=""\n', '', TRC),
 ('Y13 serve_start: SERVE_LOG not set', C, '    SERVE_LOG=$slog\n', '', TRC),
 ('Y14 end_daemon: a stop not 0 passes', C, '    elif [ "$SERVE_RC" != 0 ]; then\n        daemon_wrong', '    elif false; then\n        daemon_wrong', TRC),
